function verifyReach(){const importer=fs.readFileSync(IMPORTER,'utf8'),report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8'));assert((importer.match(/home\/mobile-composition\.css\?/g)||[]).length===1,'importer target cardinality drift');const importers=sh("git grep -l -F 'mobile-composition.css?v=' -- assets/css || true").split(/\r?\n/).filter(Boolean).sort();assert(JSON.stringify(importers)===JSON.stringify([IMPORTER]),'target importer drift '+JSON.stringify(importers));const tracked=new Set(cp.execFileSync('git',['ls-files','-z','assets/css'],{encoding:'utf8'}).split('\0').filter(f=>f.endsWith('.css'))),importRe=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi,normImport=(v,from)=>{v=v.replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))return v.replace(/^\/+/, '');if(v.startsWith('assets/'))return v;return path.posix.normalize(path.posix.join(path.posix.dirname(from),v));},imports=f=>{const src=fs.readFileSync(f,'utf8'),out=[];let m;importRe.lastIndex=0;while((m=importRe.exec(src)))out.push(normImport(m[1],f));return out;};const pages=[];for(const page of report.pageAssets){const seen=new Set(),stack=[...(page.css||[]).filter(f=>tracked.has(f))];let hit=false;while(stack.length){const f=stack.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break;}for(const n of imports(f))if(tracked.has(n))stack.push(n);}if(hit)pages.push(page.page);}assert(JSON.stringify(pages.sort())===JSON.stringify([PAGE]),'active reach drift '+JSON.stringify(pages));console.log(`REACH AUTHORITY PASS|page=${PAGE}|importer=${IMPORTER}|target=${TARGET}|pages=1`);}
function verify(p){assert(p.declarations.length===183,'decl drift '+p.declarations.length);assert(p.dead.length===17,'dead drift '+p.dead.length);const got=p.dead.map(d=>[d.context||'<global>',d.selector,d.property,d.value,d.winnerValue]);assert(JSON.stringify(got)===JSON.stringify(expected),'dead rows drift');const selectors=new Set(p.dead.map(d=>d.selector)),identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(selectors.size===7,'selectors drift '+selectors.size);assert(identical===5,'identical drift '+identical);}
async function capture(browser,tag){const out={};for(const width of widths){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),p=await ctx.newPage();await p.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort();});await p.goto(`http://127.0.0.1:4173/index.html?${tag}-${width}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:15000});await p.evaluate(()=>{if(!document.querySelector('.home-search-hero__filter-button')){const form=document.querySelector('.doke-search-panel__form');if(!form)throw new Error('missing canonical search form');const button=document.createElement('button');button.type='button';button.className='home-search-hero__filter-button';button.setAttribute('aria-label','Filtro diagnostic probe');button.setAttribute('data-diag-runtime-probe','home-filter-button');form.appendChild(button);}});await p.waitForTimeout(250);out[width]=await p.evaluate(()=>{const pick=(s,ps)=>{const e=document.querySelector(s);if(!e)throw new Error('missing '+s);const c=getComputedStyle(e),r=e.getBoundingClientRect(),o={};for(const k of ps)o[k]=c[k];o.rect=[r.x,r.y,r.width,r.height].map(n=>Math.round(n*1000)/1000);return o};const body=getComputedStyle(document.body);return{vars:{gutter:body.getPropertyValue('--index-mobile-gutter').trim(),cardWidth:body.getPropertyValue('--index-mobile-card-width').trim()},form:pick('.doke-search-panel__form',['display','position','width','height','minHeight','paddingTop','paddingRight','paddingBottom','paddingLeft','borderRadius','overflow']),field:pick('.home-search-hero__field',['display','position','width','height','minHeight','paddingTop','paddingRight','paddingBottom','paddingLeft','borderRadius','overflow']),input:pick('.doke-search-panel__input',['display','width','height','minHeight','paddingTop','paddingRight','paddingBottom','paddingLeft','fontSize','lineHeight']),submit:pick('.home-search-hero__mobile-submit',['position','left','right','width','height']),audio:pick('.home-search-hero__audio-button',['position','left','right','width','height']),filter:pick('.home-search-hero__filter-button',['position','left','right','width','height','borderRadius']),media:{max380:matchMedia('(max-width:380px)').matches,max390:matchMedia('(max-width:390px)').matches,max560:matchMedia('(max-width:560px)').matches},doc:{cw:document.documentElement.clientWidth,sw:document.documentElement.scrollWidth,bcw:document.body.clientWidth,bsw:document.body.scrollWidth}}});assert(out[width].doc.sw<=out[width].doc.cw,'overflow '+tag+' width='+width);await ctx.close();}return out;}
function apply(p){const src=fs.readFileSync(TARGET,'utf8'),hadFinal=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(hadFinal&&lines[lines.length-1]==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(d.property+':'),'line mismatch '+d.line);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n')+(hadFinal?'\n':''));const n=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(n[0]==='0'&&n[1]==='17'&&n[2]===TARGET,'delta '+n.join('/'));const a=parse(fs.readFileSync(TARGET,'utf8'));assert(a.declarations.length===166&&a.dead.length===0,`after ${a.declarations.length}/${a.dead.length}`);return crypto.createHash('sha256').update(fs.readFileSync(TARGET)).digest('hex');}
(async()=>{assert(sh('git rev-parse HEAD')===SHA,'wrong sha');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');verifyReach();const src=fs.readFileSync(TARGET,'utf8'),beforeBytes=Buffer.byteLength(src),parsed=parse(src);verify(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const before=await capture(browser,'before'),hash=apply(parsed),afterBytes=Buffer.byteLength(fs.readFileSync(TARGET)),after=await capture(browser,'after');await browser.close();assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');assert(sh('git diff --name-only -- assets index.html resultados.html')===TARGET,'product scope drift');assert(sh('git diff --numstat -- '+TARGET).split(/\s+/).slice(0,2).join('/')==='0/17','final numstat drift');console.log(`CANDIDATE BUILD PASS|hash=${hash}|bytes=${beforeBytes}->${afterBytes}|files=1|additions=0|deletions=17|decl=183->166|dead=17->0`);console.log(`CANDIDATE RUNTIME PASS|viewports=${widths.join(',')}|computed+rect+document/body=0-diffs|overflow=0|boundaries=380/390/560|page=${PAGE}`);fs.writeFileSync('/tmp/ux-css-debt-031-candidate-hash',hash+'\n');}finally{server.kill('SIGTERM');}})().catch(e=>{console.error(e.stack||e);try{cp.execSync(`git reset --hard ${SHA} && git clean -fdx`,{stdio:'inherit'})}catch{}process.exit(1)});